  '校准启动失败:': 'キャリブレーションの開始に失敗しました:',
  '数据采样率默认自动，使用检测到的设备采样率；视频采样率用于控制录制视频帧率。': 'データのサンプリングレートは既定で自動となり、検出したデバイスのサンプリングレートを使用します。動画のサンプリングレートは録画動画のフレームレートの制御に使用します。',
  '用于在没有真实眼动仪设备时进行测试和演示': '実際のアイトラッカーがない状態でのテストやデモに使用します',
  '同时作用于桌面式和眼镜式的实时预览、校准测试、被试窗口和回放点加载。': 'デスクトップ型とメガネ型の両方の、リアルタイムプレビュー、キャリブレーションテスト、被験者ウィンドウ、再生時の点の読み込みに適用されます。',
  '启用眼动数据 TCP 转发（6位包体长度 + UTF-8 JSON 字符串协议）': 'アイトラッキングデータの TCP 転送を有効にする（6桁のボディ長 + UTF-8 JSON 文字列プロトコル）',
  '暂无眼动记录可导出，请先在录制模块生成数据': 'エクスポートできるアイトラッキング記録がありません。先に録画モジュールでデータを生成してください',
