  '全部显示': 'すべて表示',
  '完整眨眼区间（按眼计）：': '完全なまばたき区間（眼ごと）：',
  '完整时长合计': '完全な持続時間の合計',
  '未观察到完整配对，次数缺失': '完全なペアが観測されていないため、回数は欠損です',
  '源区间无空间位置，未分配到 AOI': '元区間に空間位置がないため、AOI に割り当てられていません',
  '未配对阶段': '未ペアの段階',
  '瞳孔数据': '瞳孔データ',
  '瞳孔直径 (mm)': '瞳孔径 (mm)',
  '完整眨眼起始事件数（按眼）': '完全なまばたき開始イベント数（眼ごと）',
  '所选范围眨眼区间重叠时长（按眼相加）': '選択範囲内のまばたき区間の重複時間（眼ごとの合計）',
  '起始眨眼事件平均完整时长': '開始まばたきイベントの平均完全持続時間',
  'AOI总停留时长': 'AOI総滞留時間',
  '眨眼仅统计已完整配对的源区间；按源眼别分别计数，左右同时发生也各计一次，未提供眼别的事件保留未指定。次数按起始时间落入左闭右开时间窗计数；重叠时长单独裁切并按眼相加，平均时长仍使用起始事件的完整源时长。': 'まばたきは完全にペアになった元区間のみを集計します。元の眼別ごとに個別にカウントし、左右同時に発生した場合もそれぞれ1回とし、眼別が提供されていないイベントは未指定のまま残します。回数は開始時刻が左閉右開の時間窓に入るかで数えます。重複時間は個別に切り出して眼ごとに合計し、平均持続時間は引き続き開始イベントの完全な元の持続時間を使用します。',
  '没有完整配对时保持缺失，不能认定真实眨眼为零；未配对阶段不计次数。源眨眼区间没有有效空间位置，不能据此报告 AOI 眨眼次数或持续时长。': '完全なペアがない場合は欠損のままとし、実際のまばたきがゼロだとは判断できません。未ペアの段階は回数に含めません。元のまばたき区間に有効な空間位置がないため、これに基づいて AOI のまばたき回数や持続時間を報告することはできません。',
  '刺激物筛选按眨眼起始阶段的源标签归属，只统计起始事件数及其完整源平均时长；缺少精确刺激物边界时不报告眨眼重叠时长，起始标签缺失时保持该筛选的眨眼指标缺失。': '刺激物フィルターはまばたき開始段階の元ラベルで帰属を判断し、開始イベント数とその完全な元の平均持続時間のみを集計します。正確な刺激物の境界がない場合はまばたきの重複時間を報告せず、開始ラベルが欠けている場合はそのフィルターのまばたき指標を欠損のままとします。',
  '部分记录存在未配对或异常眨眼阶段；完整区间统计不代表该记录全部真实眨眼均已检测。': '一部の記録に未ペアまたは異常なまばたき段階があります。完全区間の統計は、その記録の実際のまばたきがすべて検出されたことを意味しません。',
  '当前记录的眼跳幅度/速度包含像素与归一化两种单位，未混合计算；请按相同单位分组比较。': '現在の記録のサッカード振幅/速度にはピクセルと正規化の2種類の単位が含まれており、混在させて計算していません。同じ単位でグループ化して比較してください。',
  '像素眼跳指标依赖场景分辨率与成像条件，不能直接解释为视角或跨设备物理运动差异。': 'ピクセル単位のサッカード指標はシーンの解像度と撮像条件に依存するため、視角やデバイス間の物理的な運動の差として直接解釈することはできません。',
  '全记录瞳孔均值使用当前筛选范围内合格瞳孔采样的毫米直径，允许无有效注视坐标的样本；AOI瞳孔统计另要求有效坐标。左右眼均有效时先取双眼均值，仅一眼有效时使用该眼。': '記録全体の瞳孔平均は、現在の絞り込み範囲内で適格な瞳孔サンプルのミリメートル径を使用し、有効な注視座標のないサンプルも含めます。AOIの瞳孔統計ではさらに有効な座標が必要です。左右の眼がともに有効な場合は先に両眼の平均を取り、片眼のみ有効な場合はその眼を使用します。',
  '记录选择': '記録の選択',
