  '缺少 PupilCore 后端程序，请重新安装包含 PupilCore 的版本。': 'PupilCore のバックエンドプログラムがありません。PupilCore を含むバージョンを再インストールしてください。',
  '端口被占用': 'ポートが使用中です',
  '眼动服务启动失败': 'アイトラッキングサービスの起動に失敗しました',
  '不可用': '利用不可',
  '自定义分数：10−2×官方公式对照角度（°），限制1–10分，越高越好；非厂商评分。剔除样本不参与评分，请同时查看P95和有效率。尚未设置精度合格标准。': 'カスタムスコア：10−2×公式式との比較角度（°）、1–10点に制限、高いほど良い。メーカーのスコアではありません。除外したサンプルはスコアに含まれません。P95 と有効率も併せて確認してください。精度の合格基準はまだ設定されていません。',
  '角度误差不可用：缺少匹配内参或有效角度样本。': '角度誤差は利用できません：一致する内部パラメータまたは有効な角度サンプルがありません。',
  '请先在当前连接完成校准，再进行独立验证': '先に現在の接続でキャリブレーションを完了してから、独立検証を行ってください',
  '请完成三个独立验证目标采样': '3つの独立検証ターゲットのサンプリングを完了してください',
  '独立验证目标过于集中，请重新测试分散的三个位置': '独立検証ターゲットが集中しすぎています。分散した3つの位置で再テストしてください',
  '独立验证有效样本为空，请重新采样': '独立検証の有効サンプルが空です。再サンプリングしてください',
  '使用型号默认内参，尚非逐台实测内参。': '機種の既定の内部パラメータを使用しています。個体ごとの実測値ではありません。',
  'Pupil 原生后端': 'Pupil ネイティブバックエンド',
  '追踪器已就绪，请重新点击当前目标采样': 'トラッカーの準備ができました。現在のターゲットをもう一度クリックしてサンプリングしてください',
  '目标追踪正在初始化，请稍后点击校准按钮；视频连接保持开启': 'ターゲットトラッキングを初期化中です。しばらくしてからキャリブレーションボタンをクリックしてください。動画接続は維持されます',
  '校准拟合完成，请使用不同目标进行独立验证。': 'キャリブレーションのフィッティングが完了しました。別のターゲットで独立検証を行ってください。',
  '融合': '統合',
  '校准点覆盖不足：请重新校准，选择分散且不共线的位置': 'キャリブレーション点のカバーが不十分です。分散し、同一直線上にない位置を選んで再キャリブレーションしてください',
  '自定义分数：10−2×官方公式对照角度（°），限制1–10分，越高越好；非厂商评分。以上仅为训练结果，未独立验证，不代表精度达标。': 'カスタムスコア：10−2×公式式との比較角度（°）、1–10点に制限、高いほど良い。メーカーのスコアではありません。以上は学習結果のみで、独立検証はしておらず、精度が基準を満たすことを示すものではありません。',
  '独立验证分：不可用（无有效单眼角度样本）。': '独立検証スコア：利用不可（有効な単眼角度サンプルがありません）。',
  '追踪初始化超时，请稍后重试当前点；视频连接保持开启': 'トラッキングの初期化がタイムアウトしました。しばらくしてから現在の点を再試行してください。動画接続は維持されます',
  '追踪计算超时，请重新启动校准；视频连接保持开启': 'トラッキング計算がタイムアウトしました。キャリブレーションを再開してください。動画接続は維持されます',
  '场景视频分辨率发生变化，请重新采样当前点': 'シーン動画の解像度が変わりました。現在の点を再サンプリングしてください',
  '目标追踪丢失，请等待识别实体卡片中心后点击校准按钮重试': 'ターゲットのトラッキングを見失いました。実物のカード中心が認識されるのを待ってから、キャリブレーションボタンをクリックして再試行してください',
  '目标移动过大，请保持头部和实体卡片稳定后重试当前点': 'ターゲットの動きが大きすぎます。頭と実物のカードを安定させてから現在の点を再試行してください',
  '独立验证有效注视样本不足，请检查模型质量并继续注视实体卡片中心': '独立検証の有効な注視サンプルが不足しています。モデルの品質を確認し、実物のカード中心を注視し続けてください',
  '独立验证位置与训练目标重合，请选择不同的分散位置': '独立検証の位置が学習ターゲットと重なっています。別の分散した位置を選んでください',
  '场景参考帧采样不足，请保持头部和卡片稳定后重试当前点': 'シーン参照フレームのサンプリングが不足しています。頭とカードを安定させてから現在の点を再試行してください',
  '追踪进程初始化超过 60 秒，请重新启动校准并检查 Pupil 后端日志': 'トラッキングプロセスの初期化が 60 秒を超えました。キャリブレーションを再開し、Pupil バックエンドのログを確認してください',
  '目标追踪计算超过 2 秒，请重新启动校准': 'ターゲットのトラッキング計算が 2 秒を超えました。キャリブレーションを再開してください',
  '目标区域没有可追踪特征，请点击清晰的实体卡片中心': 'ターゲット領域に追跡できる特徴がありません。はっきりした実物のカード中心をクリックしてください',
  '请更新 Pupil 独立环境：native 安装 services/eye_tracking/requirements/pupil-native.txt；Capture 安装 services/eye_tracking/requirements/pupil-capture.txt': 'Pupil の独立環境を更新してください：native は services/eye_tracking/requirements/pupil-native.txt を、Capture は services/eye_tracking/requirements/pupil-capture.txt をインストールしてください',
  '未收到瞳孔数据（眼图不等于瞳孔检测结果），请检查双眼摄像头与检测状态': '瞳孔データを受信していません（眼画像は瞳孔検出結果ではありません）。両眼カメラと検出状態を確認してください',
  '仅收到 2D/其他检测数据，3D 瞳孔检测未输出': '2D/その他の検出データのみ受信しており、3D 瞳孔検出が出力されていません',
